 public partial class MainWindow : Window {
  List<TweakItem> current=new List<TweakItem>(); List<TweakItem> privacyTweaks=new List<TweakItem>(); List<SoftwareItem> software=new List<SoftwareItem>();
  public MainWindow(){InitializeComponent();Localization.Apply(this);LoadDrives();LoadRestoreStorageDrives();LoadSoftware();PrivacyBrowserList.ItemsSource=software.Where(x=>x.Category=="Приватность").ToList();privacyTweaks=BuildPrivacyTweaks();PrivacyTweaksList.ItemsSource=privacyTweaks;OsText.Text=Localization.T("Система: ")+SystemActions.DetectWindows();GpuText.Text=Localization.T("Видеокарта: ")+Localization.T(SystemActions.DetectGpu());HardwareText.Text=SystemActions.GetHardwareSummary();}
  void LoadDrives(){DriveCombo.Items.Clear();foreach(DriveInfo d in DriveInfo.GetDrives().Where(x=>x.IsReady&&x.DriveType==DriveType.Fixed)){string text=String.Format(Localization.T("Диск {0} (Свободно {1:0.0} ГБ из {2:0.0} ГБ)"),d.Name,(double)d.AvailableFreeSpace/1073741824,(double)d.TotalSize/1073741824);DriveCombo.Items.Add(new DriveChoice(text,d.RootDirectory.FullName));}if(DriveCombo.Items.Count>0)DriveCombo.SelectedIndex=0;}
  void LoadRestoreStorageDrives(){string osDrive=Path.GetPathRoot(Environment.SystemDirectory);foreach(DriveInfo d in DriveInfo.GetDrives().Where(x=>x.IsReady&&x.DriveType==DriveType.Fixed&&!String.Equals(x.RootDirectory.FullName,osDrive,StringComparison.OrdinalIgnoreCase))){RestoreStorageDriveCombo.Items.Add(new DriveChoice(String.Format(Localization.T("Диск {0} (Свободно {1:0.0} ГБ из {2:0.0} ГБ)"),d.Name,(double)d.AvailableFreeSpace/1073741824,(double)d.TotalSize/1073741824),d.RootDirectory.FullName));}if(RestoreStorageDriveCombo.Items.Count>0)RestoreStorageDriveCombo.SelectedIndex=0;else RestoreStorageDriveCombo.IsEnabled=false;}
  SoftwareItem CreateWinRar(string category){return new SoftwareItem{Name="WinRAR",Description="сжимает и распаковывает архивы RAR, ZIP и других форматов; пробная версия",Category=category,PackageId="winrar",Url="https://www.rarlab.com/rar/winrar-x64-723.exe",AllowedHostSuffixes=new string[]{"rarlab.com"},Arguments="/S /D={INSTALLDIR}",SupportsCustomPath=true,IsSupported=true};}
