   new SoftwareItem{Name="Steam",Description="магазин и библиотека: покупка, установка, обновление и запуск игр",Category="Игры",Url="https://cdn.fastly.steamstatic.com/client/installer/SteamSetup.exe",AllowedHostSuffixes=new string[]{"steamstatic.com"},Arguments="/S /D={INSTALLDIR}",SupportsCustomPath=true,IsSupported=supportsWin10,CompatibilityNote=modernNote},
   CreateWinRar("Игры"),
   new SoftwareItem{Name="VLC",Description="воспроизводит видео и музыку в большинстве распространённых форматов",Category="Монтаж и медиа",Url="https://get.videolan.org/vlc/3.0.23/win64/vlc-3.0.23-win64.exe",AllowedHostSuffixes=new string[]{"videolan.org"},ExpectedSha256="3b52a763a789562399f2e31063c9e545ca0ff28fa464e00b4af661fd62a6260d",Arguments="/S /D={INSTALLDIR}",SupportsCustomPath=true,IsSupported=true},
   new SoftwareItem{Name="HandBrake",Description="перекодирует и сжимает видео, чтобы уменьшить размер или подготовить файл для публикации",Category="Монтаж и медиа",Url="https://github.com/HandBrake/HandBrake/releases/download/1.11.2/HandBrake-1.11.2-x86_64-Win_GUI.exe",AllowedHostSuffixes=new string[]{"github.com","githubusercontent.com"},Arguments="/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /DIR=\"{INSTALLDIR}\"",SupportsCustomPath=true,IsSupported=supportsWin10,CompatibilityNote=modernNote},
   new SoftwareItem{Name="Audacity",Description="записывает и редактирует звук: обрезает дорожки и помогает убрать шум",Category="Монтаж и медиа",Url="https://github.com/audacity/audacity/releases/download/Audacity-4.0.2/audacity-win-4.0.2-x86_64.msi",AllowedHostSuffixes=new string[]{"github.com","githubusercontent.com"},FileExtension=".msi",Arguments="/passive /norestart",ExpectedSha256="ff6cad670befee96fee563056965fa5e17bfa8c7ea3aba10c461c18799409e22",IsSupported=supportsWin10,CompatibilityNote=modernNote},
   new SoftwareItem{Name="OBS Studio",Description="записывает экран и игры, а также ведёт прямые трансляции",Category="Монтаж и медиа",Url="https://cdn-fastly.obsproject.com/downloads/OBS-Studio-33.0.1-Windows-x64-Installer.exe",AllowedHostSuffixes=new string[]{"obsproject.com"},IsSupported=supportsWin10,CompatibilityNote=modernNote},
   new SoftwareItem{Name="K-Lite Codec Pack Standard",Description="добавляет кодеки и плеер MPC-HC для воспроизведения многих видео- и аудиоформатов",Category="Монтаж и медиа",Url="https://files2.codecguide.com/K-Lite_Codec_Pack_2020_Standard.exe",AllowedHostSuffixes=new string[]{"codecguide.com"},ExpectedSha256="3caf9d253f788937d1a1b665cf67ffc3b75dfb48a998ac09f3ac3f47f3252941",IsSupported=true},
   CreateWinRar("Монтаж и медиа"),
   new SoftwareItem{Name="LibreOffice",Description="создаёт и редактирует документы, таблицы и презентации; открывает файлы Office",Category="Работа и учёба",Url="https://download.documentfoundation.org/libreoffice/stable/26.8.3/win/x86_64/LibreOffice_26.8.3_Win_x86-64.msi",AllowedHostSuffixes=new string[]{"documentfoundation.org"},FileExtension=".msi",ExpectedSha256="0e6918c273eabbdbbd800ee0dacbbf130a14c13c2e4cec861b06dd59e015bf94",Arguments="/passive /norestart",IsSupported=supportsWin10,CompatibilityNote=modernNote},
   new SoftwareItem{Name="SumatraPDF",Description="быстро открывает PDF, EPUB, комиксы и другие документы для чтения",Category="Работа и учёба",Url="https://www.sumatrapdfreader.org/dl/rel/3.6.1/SumatraPDF-3.6.1-64-install.exe",AllowedHostSuffixes=new string[]{"sumatrapdfreader.org"},Arguments="-install",IsSupported=true},
   new SoftwareItem{Name="Notepad++",Description="редактирует текст и код с вкладками, поиском и подсветкой синтаксиса",Category="Работа и учёба",Url="https://github.com/notepad-plus-plus/notepad-plus-plus/releases/download/v8.9.9.1/npp.8.9.9.1.Installer.x64.exe",AllowedHostSuffixes=new string[]{"github.com","githubusercontent.com"},Arguments="/S /D={INSTALLDIR}",SupportsCustomPath=true,IsSupported=true},
   CreateWinRar("Работа и учёба"),
   new SoftwareItem{Name="Mullvad Browser",Description="браузер блокирует трекеры и помогает защититься от цифрового отпечатка; сам по себе не скрывает IP",Category="Приватность",PackageId="mullvad-browser",Url="https://mullvad.net/download/browser/win64/latest",AllowedHostSuffixes=new string[]{"mullvad.net"},Arguments="/S",IsSupported=supportsWin10,CompatibilityNote=Localization.T("Требуется Windows 10 или новее, 64-разрядная версия.")},
   new SoftwareItem{Name="7-Zip",Description="сжимает и распаковывает архивы 7z, ZIP, RAR и других форматов",Category="Утилиты",Url="https://www.7-zip.org/a/7z2606-x64.exe",AllowedHostSuffixes=new string[]{"7-zip.org"},Arguments="/S /D={INSTALLDIR}",SupportsCustomPath=true,IsSupported=true},
   new SoftwareItem{Name="Everything",Description="находит файлы и папки по имени почти мгновенно, не перебирая их вручную",Category="Утилиты",Url="https://www.voidtools.com/Everything-1.4.1.1032.x64-Setup.exe",AllowedHostSuffixes=new string[]{"voidtools.com"},IsSupported=true},
   CreateWinRar("Утилиты")
  };var view=CollectionViewSource.GetDefaultView(software);view.GroupDescriptions.Clear();view.GroupDescriptions.Add(new PropertyGroupDescription("Category"));SoftwareList.ItemsSource=view;}
  void OsCombo_SelectionChanged(object sender,SelectionChangedEventArgs e){if(OsText!=null&&OsCombo.SelectedItem is ComboBoxItem)OsText.Text=Localization.T("Выбрана система: ")+((ComboBoxItem)OsCombo.SelectedItem).Content;}
  void DetectOs_Click(object s,RoutedEventArgs e){OsText.Text=Localization.T("Система: ")+SystemActions.DetectWindows();}
  void Profile_Click(object s,RoutedEventArgs e){string key=Convert.ToString(((FrameworkElement)s).Tag);ProfileTitle.Text=((System.Windows.Controls.Button)s).Content.ToString();current=BuildProfile(key);TweaksList.ItemsSource=null;TweaksList.ItemsSource=current;ApplySoftwareProfile(key);}
  void ApplySoftwareProfile(string profile){string[] recommended;if(profile=="Games")recommended=new string[]{"Steam","7-Zip","WinRAR"};else if(profile=="OldPc")recommended=new string[]{"7-Zip","SumatraPDF","Notepad++","VLC","WinRAR"};else if(profile=="Media")recommended=new string[]{"VLC","HandBrake","Audacity","OBS Studio","K-Lite Codec Pack Standard","WinRAR"};else if(profile=="Work")recommended=new string[]{"LibreOffice","SumatraPDF","Notepad++","7-Zip","Everything","WinRAR"};else recommended=new string[0];string targetCategory=profile=="Games"?"Игры":profile=="Media"?"Монтаж и медиа":profile=="Work"?"Работа и учёба":"Утилиты";var selection=new HashSet<string>(recommended,StringComparer.OrdinalIgnoreCase);foreach(SoftwareItem item in software)item.IsSelected=(selection.Contains(item.Name)&&item.IsSupported)&&(item.PackageId!="winrar"||item.Category==targetCategory);CollectionViewSource.GetDefaultView(software).Refresh();StatusText.Text=Localization.T("Отметки программ обновлены для выбранного профиля; их можно изменить вручную.");}
  List<TweakItem> BuildProfile(string p){var a=new List<TweakItem>();Action add(string n,string d,Action x){a.Add(new TweakItem{Name=n,Description=d,Apply=x,IsSelected=true});return x;}if(p=="Games"){add("Максимальная производительность","добавить схему питания через powercfg",()=>SystemActions.Run("powercfg.exe","-duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61"));add("Игровой режим без DVR","отключить запись Xbox Game Bar текущего пользователя",()=>{SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\GameDVR","AppCaptureEnabled",0);SystemActions.SetDword(@"System\GameConfigStore","GameDVR_Enabled",0);});add("Снижение фоновой активности","отключить приложения в фоне для текущего пользователя",()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications","GlobalUserDisabled",1));}
   if(p=="OldPc"){add("Упростить интерфейс","отключить анимацию окон",()=>SystemActions.SetDword(@"Control Panel\Desktop\WindowMetrics","MinAnimate",0));add("Отключить прозрачность","тема текущего пользователя",()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize","EnableTransparency",0));add("Очистить временные файлы","временные каталоги Windows и пользователя",SystemActions.CleanTemp);add("Уменьшить нагрузку SysMain","перевести SysMain в ручной запуск",()=>SystemActions.StopService("SysMain"));add("Сбалансированная схема","включить план питания Balanced",()=>SystemActions.Run("powercfg.exe","/setactive 381b4222-f694-41f0-9685-ff5bb260df2e"));}
   if(p=="Media"){add("Приоритет программ переднего плана","Win32PrioritySeparation = 0x26",()=>SystemActions.SetDwordMachine(@"SYSTEM\CurrentControlSet\Control\PriorityControl","Win32PrioritySeparation",0x26));add("Очистить временные файлы","освободить используемые временные каталоги",SystemActions.CleanTemp);add("Файл подкачки","оставить под управлением Windows",()=>SystemActions.Run("wmic.exe","computersystem set AutomaticManagedPagefile=True"));}
   if(p=="Work"){add("Показывать расширения файлов","проводник текущего пользователя",()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced","HideFileExt",0));add("Показывать скрытые файлы","проводник текущего пользователя",()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced","Hidden",1));add("Очистить кэш DNS","сбросить кэш системного DNS",()=>SystemActions.Run("ipconfig.exe","/flushdns"));add("Уменьшить рекламные предложения","отключить советы и подсказки",()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager","SystemPaneSuggestionsEnabled",0));}
   return a;}
  List<TweakItem> BuildPrivacyTweaks(){return new List<TweakItem>{
    new TweakItem{Name="Отключить рекламный идентификатор",Description="для текущего пользователя; приложения могут использовать его для персонализированной рекламы",IsSelected=true,Apply=()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo","Enabled",0)},
    new TweakItem{Name="Отключить персонализированные советы",Description="уменьшает рекомендации Windows на основе диагностических данных",IsSelected=true,Apply=()=>SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\Privacy","TailoredExperiencesWithDiagnosticDataEnabled",0)},
    new TweakItem{Name="Отключить рекламные предложения и советы в меню Пуск",Description="текущий пользователь; часть предложений зависит от версии Windows",IsSelected=true,Apply=()=>{SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager","SystemPaneSuggestionsEnabled",0);SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager","SubscribedContent-338388Enabled",0);SystemActions.SetDword(@"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager","SubscribedContent-338389Enabled",0);}},
    new TweakItem{Name="Отключить журнал активности и синхронизацию действий",Description="политика Windows; может быть недоступна или проигнорирована в отдельных редакциях",IsSelected=true,Apply=()=>{SystemActions.SetDwordMachine(@"SOFTWARE\Policies\Microsoft\Windows\System","EnableActivityFeed",0);SystemActions.SetDwordMachine(@"SOFTWARE\Policies\Microsoft\Windows\System","PublishUserActivities",0);SystemActions.SetDwordMachine(@"SOFTWARE\Policies\Microsoft\Windows\System","UploadUserActivities",0);}},
    new TweakItem{Name="Ограничить диагностические данные до обязательного минимума",Description="Windows продолжит отправлять диагностические данные, необходимые для работы и обновлений; доступность параметра зависит от редакции и версии",IsSelected=true,Apply=()=>SystemActions.SetDwordMachine(@"SOFTWARE\Policies\Microsoft\Windows\DataCollection","AllowTelemetry",1)}
  };}
  void Restore_Click(object s,RoutedEventArgs e){try{SystemActions.CreateRestorePoint();StatusText.Text=Localization.T("Точка восстановления создана.");System.Windows.MessageBox.Show(Localization.T("Точка восстановления создана."),"WinOptimizer");}catch(Exception x){System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void OpenProtection_Click(object s,RoutedEventArgs e){try{SystemActions.OpenSystemProtection();}catch(Exception x){System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void EnableProtection_Click(object s,RoutedEventArgs e){string prompt=Localization.T("Включить защиту системы на диске Windows? Затем откроются настройки, где можно выделить место для точек.");if(System.Windows.MessageBox.Show(prompt,Localization.T("Защита системы"),MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{SystemActions.EnableSystemProtection();ProtectionStatusText.Text=Localization.T("Windows приняла запрос на включение защиты. Проверьте состояние системного диска и назначьте место для точек в открывшемся окне.");SystemActions.OpenSystemProtection();}catch(Exception x){System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void ApplyRestoreStorage_Click(object s,RoutedEventArgs e){DriveChoice choice=RestoreStorageDriveCombo.SelectedItem as DriveChoice;int size;if(choice==null||!Int32.TryParse(RestoreStorageSizeText.Text,out size)){System.Windows.MessageBox.Show(Localization.T("Выберите диск и укажите лимит от 1 до 2048 ГБ."),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Warning);return;}string prompt=Localization.T("Перенести хранилище теневых копий системного диска на ")+choice.Label+Localization.T("? Старые точки восстановления могут быть удалены. Продолжить?");if(System.Windows.MessageBox.Show(prompt,Localization.T("Изменить хранилище точек"),MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{SystemActions.MoveRestoreStorage(choice.Path,size);System.Windows.MessageBox.Show(Localization.T("Хранилище теневых копий настроено."),Localization.T("Защита системы"),MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception x){System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void RefreshHardware_Click(object s,RoutedEventArgs e){HardwareText.Text=SystemActions.GetHardwareSummary();}
  void DeviceManager_Click(object s,RoutedEventArgs e){try{Process.Start(new ProcessStartInfo("mmc.exe","devmgmt.msc"){UseShellExecute=true});}catch(Exception x){System.Windows.MessageBox.Show(Localization.T("Не удалось открыть диспетчер устройств.")+" "+x.Message,Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void Apply_Click(object s,RoutedEventArgs e){var selected=current.Where(x=>x.IsSelected).ToList();if(selected.Count==0)return;string prompt=Localization.T("Создать точку восстановления и применить ")+selected.Count+Localization.T(" операций? Некоторые изменения вступят в силу после перезагрузки.");if(System.Windows.MessageBox.Show(prompt,Localization.T("Подтверждение"),MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{SystemActions.CreateRestorePoint();foreach(var t in selected)t.Apply();System.Windows.MessageBox.Show(Localization.T("Отмеченные изменения применены."),"WinOptimizer");}catch(Exception x){System.Windows.MessageBox.Show(Localization.T("Операция остановлена: ")+Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void ApplyPrivacy_Click(object s,RoutedEventArgs e){var selected=privacyTweaks.Where(x=>x.IsSelected).ToList();if(selected.Count==0){System.Windows.MessageBox.Show(Localization.T("Отметьте параметры Windows, которые хотите изменить."));return;}string prompt=Localization.T("Создать точку восстановления и применить ")+selected.Count+Localization.T(" параметров приватности? Некоторые параметры зависят от версии Windows и могут изменить рекомендации или журнал активности.");if(System.Windows.MessageBox.Show(prompt,Localization.T("Настройки приватности"),MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{SystemActions.CreateRestorePoint();foreach(TweakItem item in selected)item.Apply();System.Windows.MessageBox.Show(Localization.T("Выбранные параметры применены. Для некоторых из них может потребоваться выход из системы или перезагрузка."),"WinOptimizer");}catch(Exception x){System.Windows.MessageBox.Show(Localization.T("Операция остановлена: ")+Localization.T(x.Message),Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  async void InstallPrivacyBrowser_Click(object s,RoutedEventArgs e){var selected=software.Where(x=>x.Category=="Приватность"&&x.IsSelected&&x.IsSupported).ToList();if(selected.Count==0){System.Windows.MessageBox.Show(Localization.T("Отметьте Mullvad Browser для установки. Для Tor Browser откройте официальную страницу загрузки."));return;}if(System.Windows.MessageBox.Show(Localization.T("Mullvad Browser будет загружен с официального сайта, проверен по цифровой подписи и установлен в стандартную папку пользователя. Продолжить?"),Localization.T("Установка браузера"),MessageBoxButton.YesNo,MessageBoxImage.Information)!=MessageBoxResult.Yes)return;try{foreach(SoftwareItem item in selected){StatusText.Text=Localization.T("Загрузка и установка: ")+item.Name;await InstallerService.DownloadAndRunAsync(item,Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),null);}StatusText.Text=Localization.T("Установка браузера завершена.");System.Windows.MessageBox.Show(Localization.T("Mullvad Browser установлен."),Localization.T("Приватность"));}catch(Exception x){StatusText.Text=Localization.T("Не удалось установить браузер.");System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка установки"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void TorDownload_Click(object s,RoutedEventArgs e){try{Process.Start(new ProcessStartInfo("https://www.torproject.org/download/"){UseShellExecute=true});}catch(Exception x){System.Windows.MessageBox.Show(Localization.T("Не удалось открыть страницу Tor Project. ")+x.Message,Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void OpenPrivacySettings_Click(object s,RoutedEventArgs e){try{Process.Start(new ProcessStartInfo("ms-settings:privacy"){UseShellExecute=true});}catch(Exception x){System.Windows.MessageBox.Show(Localization.T("Не удалось открыть параметры приватности Windows. ")+x.Message,Localization.T("Ошибка"),MessageBoxButton.OK,MessageBoxImage.Error);}}
  void Browse_Click(object s,RoutedEventArgs e){using(var d=new FolderBrowserDialog()){d.Description=Localization.T("Выберите папку установки");if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){DriveCombo.Items.Insert(0,new DriveChoice(d.SelectedPath,d.SelectedPath));DriveCombo.SelectedIndex=0;}}}
  async void Install_Click(object s,RoutedEventArgs e){var selected=software.Where(x=>x.IsSelected&&x.IsSupported).GroupBy(x=>String.IsNullOrWhiteSpace(x.PackageId)?x.Name:x.PackageId,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();if(selected.Count==0){System.Windows.MessageBox.Show(Localization.T("Отметьте программы, доступные для этой версии Windows."));return;}DriveChoice choice=DriveCombo.SelectedItem as DriveChoice;if(choice==null){System.Windows.MessageBox.Show(Localization.T("Выберите папку установки."));return;}if(System.Windows.MessageBox.Show(Localization.T("Для каждой выбранной программы приложение скачает временный установщик, проверит его SHA-256 или цифровую подпись, запустит установку и удалит временный файл после её завершения. Установщики с собственным мастером покажут своё окно. Папка назначения передаётся только тем программам, которые её поддерживают."),Localization.T("Установка программ"),MessageBoxButton.OKCancel,MessageBoxImage.Information)!=MessageBoxResult.OK)return;Progress.Value=0;try{for(int i=0;i<selected.Count;i++){var item=selected[i];StatusText.Text=Localization.T("Скачивание и установка: ")+Localization.T(item.Name);await InstallerService.DownloadAndRunAsync(item,choice.Path,(done,total)=>Dispatcher.Invoke(()=>Progress.Value=total>0?Math.Min(100,(double)done/total*100):0));Progress.Value=(double)(i+1)/selected.Count*100;}StatusText.Text=Localization.T("Установка выбранных программ завершена. Временные установщики удалены.");}catch(Exception x){StatusText.Text=Localization.T("Установка остановлена.");System.Windows.MessageBox.Show(Localization.T(x.Message),Localization.T("Ошибка установки"),MessageBoxButton.OK,MessageBoxImage.Error);}finally{Progress.IsIndeterminate=false;}}
  async void Drivers_Click(object s,RoutedEventArgs e){if(System.Windows.MessageBox.Show(Localization.T("Приложение выполнит поиск драйверов, предлагаемых настроенным Windows Update, и скачает найденные пакеты. Драйверы автоматически установлены не будут. Продолжить?"),Localization.T("Драйверы Windows"),MessageBoxButton.YesNo,MessageBoxImage.Information)!=MessageBoxResult.Yes)return;DriverButton.IsEnabled=false;HardwareDriverButton.IsEnabled=false;Progress.Value=0;try{DriverDownloadResult result=await DriverUpdateService.SearchAndDownloadAsync((value,message)=>Dispatcher.BeginInvoke(new Action(()=>{Progress.Value=value;StatusText.Text=Localization.T(message);})));Progress.Value=100;StatusText.Text=Localization.T(result.ResultMessage);if(result.AvailableCount>0){string titles=String.Join("\n",result.Titles.Take(12).ToArray());if(result.Titles.Length>12)titles+="\n… и ещё "+(result.Titles.Length-12);string report=Localization.T(result.ResultMessage)+"\n"+Localization.T("Скачано: ")+result.DownloadedCount+Localization.T(" из ")+result.AvailableCount+".\n\n"+titles;System.Windows.MessageBox.Show(report,Localization.T("Драйверы Windows"),MessageBoxButton.OK,MessageBoxImage.Information);}else System.Windows.MessageBox.Show(Localization.T(result.ResultMessage),Localization.T("Драйверы Windows"),MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception x){Progress.Value=0;StatusText.Text=Localization.T("Не удалось получить драйверы.");System.Windows.MessageBox.Show(Localization.T("Windows Update не смог выполнить поиск или загрузку драйверов.\n\n")+Localization.T(x.Message),Localization.T("Драйверы Windows"),MessageBoxButton.OK,MessageBoxImage.Error);}finally{DriverButton.IsEnabled=true;HardwareDriverButton.IsEnabled=true;}}
  sealed class DriveChoice{public string Label{get;private set;}public string Path{get;private set;}public DriveChoice(string l,string p){Label=l;Path=p;}public override string ToString(){return Label;}}
 }
}
